namespace Fanex.AccountingReports.Misc.Services.Implement.AutoGeneratedReport
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Data;
    using System.IO;
    using System.Linq;
    using System.Net;
    using Fanex.AccountingReports.Core.Configurations;
    using Fanex.AccountingReports.Core.Services.Impl;
    using Fanex.AccountingReports.Core.Web;
    using Fanex.AccountingReports.Misc.Models.AutoGeneratedReport;
    using Fanex.AccountingReports.Misc.Services.Interface.AutoGeneratedReport;
    using Fanex.Common;
    using Fanex.Data;
    using Fanex.NAP.Core.Configuration;
    using Fanex.ServiceManagement.Utility;
    
    public class AutoGeneratedTodayReport : IAutoGeneratedTodayReport
    {
        private string _ip = AppSettings.IP;
        private string _password = AppSettings.Password;
        private string _username = AppSettings.UserName;

        private NetworkCredential _networkCredential;

        private List<ReportGroup> _reportList = null;
        private List<ReportGroup> _todayReports = null;

        public AutoGeneratedTodayReport()
        {
            _reportList = new List<ReportGroup>();

            if (AppSettings.IsAuthenticate)
            {
                if (AppSettings.IsEncryptPassword)
                {
                    _password = Cryptography.CfsDeCrypt(_password);
                }

                _networkCredential = new NetworkCredential(_username, _password);
            }
        }

        /// <summary>
        /// Get Reports belong to user.
        /// </summary>
        /// <returns>Return reports belong to user.</returns>
        public List<ReportGroup> GetReports()
        {
            List<ReportGroup> reportList = new List<ReportGroup>();

            var roleAccess = AppSession.RoleAccess;

            var id = NapSettings.Settings.SiteId;
            var environment = NapSettings.Settings.Environment;

            using (ObjectDb db = new ObjectDb("NAP_Function_GetBySite"))
            {
                Hashtable param = new Hashtable();
                param.Add("environment", environment);
                param.Add("siteid", id);
                param.Add("isactive", true);

                var data = db.ExecuteDataSet(param).Tables[0].AsEnumerable().ToList();

                GetReportByUser(data, AppSettings.AutoGenerateReportFunctionId);

                reportList = _reportList.OrderBy(s => s.GroupName).ToList();
            }

            return reportList;
        }

        public List<ReportGroup> GetTodayReports()
        {
            var reportsByUser = GetReports();

            if (AppSettings.IsAuthenticate)
            {
                using (new NetworkConnection(@"\\" + _ip, _networkCredential))
                {
                    return GetTodayReportsByUser(reportsByUser);
                }
            }
            else
            {
                return GetTodayReportsByUser(reportsByUser);
            }
        }       

        public List<ReportGroup> GetTodayReportsByUser(List<ReportGroup> reportsByUser)
        {
            _todayReports = new List<ReportGroup>();

            var groupReports = reportsByUser.Select(s => s.GroupName).Distinct().ToList();
            foreach (var groupReport in groupReports)
            {
                var reportByGroup = reportsByUser.Where(s => s.GroupName == groupReport).ToList();
                foreach (var reportGroup in reportByGroup)
                {
                    foreach (var reportItem in reportGroup.Reports)
                    {
                        string currentReportParentFolder = Path.Combine(AppSettings.AutoGenerateReportParentFolder, reportItem.FolderName);

                        if (File.Exists(currentReportParentFolder))
                        {
                            ProcessFile(reportItem.FunctionKey, reportItem.Description, currentReportParentFolder);
                        }
                        else if (Directory.Exists(currentReportParentFolder))
                        {
                            ProcessDirectory(reportItem.FunctionKey, reportItem.Description, currentReportParentFolder);
                        }
                    }
                }
            }

            return _todayReports.OrderBy(p => p.GroupName).ToList();
        }
       
        private static string GetParentFolderName(List<DataRow> data, int id)
        {
            var parentData = data.Where(s => Converter.ToInt(s["FunctionId"]) == id).ToList();
            string parentFolderName = Converter.ToString2(parentData[0]["FunctionKey"]);
            return parentFolderName;
        }      

        private void GetReportByUser(List<DataRow> data, int id)
        {
            var subData = data.Where(s => Converter.ToInt(s["ParentId"]) == id);
            foreach (DataRow row in subData)
            {
                int functionId = Converter.ToInt(row["FunctionId"]);
                string functionKey = Converter.ToString2(row["FunctionKey"]);

                bool hasPermission = PermissionService.HasReadPermission(functionKey);
                if (!hasPermission)
                {
                    continue;
                }

                var leafData = data.Where(s => Converter.ToInt(s["ParentId"]) == functionId).ToList();
                if (leafData.Count == 0)
                {
                    string parentFolderName = GetParentFolderName(data, id);
                    AssignReportInfo(id, row, functionId, functionKey, parentFolderName);
                }
                else
                {
                    GetReportByUser(data, functionId);
                }
            }
        }

        private void AssignReportInfo(int id, DataRow row, int functionId, string functionKey, string parentFolderName)
        {
            ReportGroup group = new ReportGroup();
            group.GroupName = Converter.ToString2(row["Description"]);
            group.Reports.Add(new Report() 
            {
                Name = Converter.ToString2(row["FunctionName"]),
                Description = Converter.ToString2(row["Description"]),
                FolderName = functionKey,
                ParentFolderName = parentFolderName,
                FunctionKey = functionKey
            });

            _reportList.Add(group);
        }

        private void ProcessDirectory(string functionKey, string reportDescription, string directory)
        {
            string[] files = Directory.GetFiles(directory);
            foreach (string file in files)
            {
                ProcessFile(functionKey, reportDescription, file);
            }

            string[] subDirectories = Directory.GetDirectories(directory);
            foreach (var subDirectory in subDirectories)
            {
                ProcessDirectory(functionKey, reportDescription, subDirectory);
            }
        }

        private void ProcessFile(string functionKey, string reportDescription, string reportPath)
        {
            bool hasPermission = PermissionService.HasReadPermission(functionKey);
            if (!hasPermission)
            {
                return;
            }

            DateTime latestModifyDate = File.GetLastWriteTime(reportPath);
            if (latestModifyDate.Date == DateTime.Today.AddDays(-0).Date)
            {
                var report = new Report()
                {
                    Name = Path.GetFileName(reportPath),
                    Description = reportDescription,
                    FolderName = reportPath.Replace(string.Format("{0}\\", AppSettings.AutoGenerateReportParentFolder), string.Empty),
                    GeneratedDate = latestModifyDate.ToString("yyyy-MM-dd"),
                    GeneratedDateFull = latestModifyDate,
                    FunctionKey = functionKey
                };

                ReportGroup group = _todayReports.Where(s => s.GroupName == reportDescription).Distinct().FirstOrDefault();
                if (group == null)
                {
                    group = new ReportGroup();
                    group.GroupName = reportDescription;
                    
                    _todayReports.Add(group);
                }

                group.Reports.Add(report);
                group.Reports = group.Reports.OrderByDescending(s => s.GeneratedDateFull).ToList();
            }
        }
    }
}